function platformAccount(){const e=Vibe.escape,u=Vibe.user;document.querySelector('#main').innerHTML=`<h1>Your account</h1><p>${e(u.name)} · ${e(u.email)}</p><div class="panel"><h2>Your offerings</h2><p>Vibe One and Vibe Law are separate offerings on one platform.</p>${['one','law'].map(k=>`<div class="row"><strong>Vibe ${k==='one'?'One':'Law'}</strong><span>${u.access[k]?'Local trial active':'Not activated'}</span><button data-edition="${k}">${u.access[k]?'Make default':'Activate local trial'}</button></div>`).join('')}<p>Billing is not connected. No payment or paid subscription is created here.</p></div><div class="panel"><h2>Codex connection</h2><p>Builds use the signed-in Codex CLI on this computer. Claude and API keys are not enabled in this version.</p><a href="#build">Open build workspace</a></div><button id="signout">Sign out</button>`;document.querySelector('#signout').onclick=Vibe.logout;document.querySelectorAll('[data-edition]').forEach(b=>b.onclick=async()=>{try{const edition=b.dataset.edition;if(!Vibe.user.access[edition])Vibe.user=await Vibe.api('/access',{edition});Vibe.user=await Vibe.api('/me',{defaultEdition:edition});platformAccount();}catch(e){alert(e.message);}});}
(async()=>{await Vibe.require();window.PLATFORM_STORAGE_KEY='vibe-workbench-'+Vibe.user.id;sessionStorage.setItem('wb-pair-token',Vibe.token);const load=src=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.body.append(s);});await load('build-ui.js');await load('app.js');document.querySelector('.local-label').textContent=Vibe.user.name;})();